",					//	Author	"v1.0";							//	Version String};//###########################################################//#		Define About Box resources							#//###########################################################resource rControlTemplate (AboutID) {	AboutID,						//	control ID	{38,5,128,280},					//	rect	statTextControl {{		0,							//	flags		0b0001000000000010,			//	more flags		0,							//	refCon		AboutID	}},};resource rTextForLETextBox2 (AboutID) {	"This Control Panel allows you to set the default privilege level that "	"will be assigned to new folders created on AppleShare¨ file servers."};//###########################################################//#		Define Warning Message resources					#//###########################################################resource rAlertString (noFSTtext) {	"73/AppleShare is currently not active.  If you continue, any changes "	"that you make will not take effect until the next time the machine "	"is restarted with AppleShare enabled./#1/^#6"	$"00"};//###########################################################//#		Define menu resources								#//###########################################################/* Source code created by DesignMaster */resource rControlList (myCtrlList) {{	serverDefsBox,	/* control resource id for Use Server Defaults check box */	separator1,		/* control resource id for separator statText */	masterPopup,	/* control resource id for Master PopUp */	separator2,		/* control resource id for separator statText */	foldersPopup,	/* control resource id for See Folders PopUp*/	filesPopup,		/* control resource id for See Files PopUp */	changesPopup,	/* control resource id for Make Changes PopUp */	ownerCheckBox,	/* control resource id for Owner is... check box */};};//----------------------------------------------------------------------------------// Common strings used by multiple menus#define nobodyString	0x00000010#define ownerString		0x00000011#define groupString		0x00000012#define oAndGString		0x00000013#define everyoneString	0x00000014resource rPString (nobodyString) { 	"Nobody"};resource rPString (ownerString) { 	"Owner"};resource rPString (groupString) { 	"Group"};resource rPString (oAndGString) { 	"Owner & Group"};resource rPString (everyoneString) { 	"Everyone"};//----------------------------------------------------------------------------------// Use Server Defaults check box controlresource rControlTemplate (serverDefsBox) {	serverDefsBox,							/* control id */ 	{3,14,15,247},							/* control rectangle */	CheckControl{{							/* control type */		0x0001,								/* flags */		0x1002,								/* more flags */		0,									/* ref con */		serverDefsBox,						/* title reference */		0x0001								/* inital value */	}};};resource rPString (serverDefsBox) { 	"Use Server Defaults"};//----------------------------------------------------------------------------------// separator bar frame controlresource rControlTemplate (separator1) {	separator1,  							/* control id */ 	{21,14,22,247},  						/* control rectangle */	rectangleControl{{  					/* control type */		0x0002,  							/* flags */		0x1000,  							/* more flags */		0        							/* ref con */	}};};//----------------------------------------------------------------------------------// Master PopUp controlresource rControlTemplate (masterPopup) {	masterPopup,  							/* control id */ 	{28,10,40,247},  						/* control rectangle */	PopUpControl{{   						/* control type */		0x0000,  							/* flags */		0x1002,  							/* more flags */		0,        							/* ref con */		100, 								/* title width */		masterPopup, 						/* menu reference */		masterItem2  						/* inital value */	}};};resource rMenu (masterPopup) {	masterPopup,  							/* id of menu */	RefIsResource*MenuTitleRefShift+RefIsResource*ItemRefShift+fAllowCache,	masterPopup,  							/* id of title string */	{		masterItem1,    					/* item reference */		masterItem2,    					/* item reference */		masterItem3,    					/* item reference */		masterItem4,    					/* item reference */		masterItem5,    					/* item reference */	};};resource rPString (masterPopup) {	" Master:"};resource rMenuItem (masterItem1) {	masterItem1, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	masterItem1,    						/* title reference */};resource rPString (masterItem1) { 	"Custom"};resource rMenuItem (masterItem2) {	masterItem2, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	masterItem2,    						/* title reference */};resource rPString (masterItem2) { 	"Private"};resource rMenuItem (masterItem3) {	masterItem3, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	masterItem3,    						/* title reference */};resource rPString (masterItem3) { 	"Public"};resource rMenuItem (masterItem4) {	masterItem4, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	masterItem4,    						/* title reference */};resource rPString (masterItem4) { 	"Drop Folder"};resource rMenuItem (masterItem5) {	masterItem5, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	masterItem5,    						/* title reference */};resource rPString (masterItem5) { 	"Bulletin Board"};//----------------------------------------------------------------------------------// separator bar frame controlresource rControlTemplate (separator2) {	separator2,  							/* control id */ 	{46,14,47,247},  						/* control rectangle */	rectangleControl{{  					/* control type */		0x0002,  							/* flags */		0x1000,  							/* more flags */		0        							/* ref con */	}};};//----------------------------------------------------------------------------------// See Folders PopUp controlresource rControlTemplate (foldersPopup) {	foldersPopup,  							/* control id */ 	{53,10,65,247}, 				 		/* control rectangle */	PopUpControl{{   						/* control type */		0x0000,  							/* flags */		0x1002,  							/* more flags */		0,        							/* ref con */		100, 								/* title width */		foldersPopup, 						/* menu reference */		foldersItem2  						/* inital value */	}};};resource rMenu (foldersPopup) {	foldersPopup,  							/* id of menu */	RefIsResource*MenuTitleRefShift+RefIsResource*ItemRefShift+fAllowCache,	foldersPopup,  							/* id of title string */	{		foldersItem1,    					/* item reference */		foldersItem2,    					/* item reference */		foldersItem3,    					/* item reference */		foldersItem4,    					/* item reference */		foldersItem5,    					/* item reference */	};};resource rPString (foldersPopup) {	" See Folders:"};resource rMenuItem (foldersItem1) {	foldersItem1, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	nobodyString,  							/* title reference */};resource rMenuItem (foldersItem2) {	foldersItem2, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	ownerString,   							/* title reference */};resource rMenuItem (foldersItem3) {	foldersItem3, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	groupString,   							/* title reference */};resource rMenuItem (foldersItem4) {	foldersItem4, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	oAndGString,   							/* title reference */};resource rMenuItem (foldersItem5) {	foldersItem5, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	everyoneString,    						/* title reference */};//----------------------------------------------------------------------------------// See Files PopUp controlresource rControlTemplate (filesPopup) {	filesPopup,  							/* control id */ 	{71,10,83,247},  						/* control rectangle */	PopUpControl{{   						/* control type */		0x0000,  							/* flags */		0x1002,  							/* more flags */		0,        							/* ref con */		100, 								/* title width */		filesPopup, 						/* menu reference */		filesItem2  						/* inital value */	}};};resource rMenu (filesPopup) {	filesPopup,  							/* id of menu */	RefIsResource*MenuTitleRefShift+RefIsResource*ItemRefShift+fAllowCache,	filesPopup,  							/* id of title string */	{		filesItem1,    						/* item reference */		filesItem2,    						/* item reference */		filesItem3,    						/* item reference */		filesItem4,    						/* item reference */		filesItem5,    						/* item reference */	};};resource rPString (filesPopup) {	" See Files:"};resource rMenuItem (filesItem1) {	filesItem1, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	nobodyString,  							/* title reference */};resource rMenuItem (filesItem2) {	filesItem2,								/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	ownerString,   							/* title reference */};resource rMenuItem (filesItem3) {	filesItem3, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	groupString,   							/* title reference */};resource rMenuItem (filesItem4) {	filesItem4, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	oAndGString,   							/* title reference */};resource rMenuItem (filesItem5) {	filesItem5, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	everyoneString,							/* title reference */};//----------------------------------------------------------------------------------// Make Changes PopUp controlresource rControlTemplate (changesPopup) {	changesPopup,  							/* control id */ 	{89,10,101,247},  						/* control rectangle */	PopUpControl{{   						/* control type */		0x0040,  							/* flags */		0x1002,  							/* more flags */		0,        							/* ref con */		100, 								/* title width */		changesPopup, 						/* menu reference */		changesItem2  						/* inital value */	}};};resource rMenu (changesPopup) {	changesPopup,  							/* id of menu */	RefIsResource*MenuTitleRefShift+RefIsResource*ItemRefShift+fAllowCache,	changesPopup,  							/* id of title string */	{		changesItem1,    					/* item reference */		changesItem2,    					/* item reference */		changesItem3,    					/* item reference */		changesItem4,    					/* item reference */		changesItem5,    					/* item reference */	};};resource rPString (changesPopup) {	" Make Changes:"};resource rMenuItem (changesItem1) {	changesItem1, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	nobodyString,							/* title reference */};resource rMenuItem (changesItem2) {	changesItem2, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	ownerString,							/* title reference */};resource rMenuItem (changesItem3) {	changesItem3, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	groupString,							/* title reference */};resource rMenuItem (changesItem4) {	changesItem4, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	oAndGString,							/* title reference */};resource rMenuItem (changesItem5) {	changesItem5, 							/* item id number */	"","",       							/* hot key*/	0,       								/* check character */	RefIsResource*ItemTitleRefShift+fXOR,	everyoneString,							/* title reference */};//----------------------------------------------------------------------------------// Owner is <Any User> check box controlresource rControlTemplate (ownerCheckBox) {	ownerCheckBox,  						/* control id */ 	{107,14,119,247},						/* control rectangle */	CheckControl{{  						/* control type */		0x0001,  							/* flags */		0x1002,  							/* more flags */		0,        							/* ref con */		ownerCheckBox,   					/* title reference */		0x0000	     						/* inital value */	}};};resource rPString (ownerCheckBox) { 	"Owner is <Any User>"};//###########################################################//#		Define icon resources								#//###########################################################resource rIcon (1) {				//	the "CDEV" icon	0x8000,							//	kind	20,								//	height	28,								//	width    $"FFFFFFFFFFFFFFFFFFFFFFFFFFFF"    $"FFFFFF000000FFFFFFFFFFFFFFFF"    $"FFFFF00000000FFFFFFFFFFFFFFF"    $"FFFFF000000000000000000FFFFF"    $"FFFFF0eeeeeee00eeeeeee0FFFFF"    $"FFFFF0eeeeee0ee0eeeeee0FFFFF"    $"FFFFF0eeeee000000eeeee0FFFFF"    $"FFFFF0eeeee030030eeeee0FFFFF"    $"FFFFF0eeeee030030eeeee0FFFFF"    $"FFFFF0eeeee000000eeeee0FFFFF"    $"cccccccccccccccccccccccccccc"    $"FccccccccccccccccccccccccccF"    $"FFFFFFF0f0f0f0ff0f0FFFFFFFFF"    $"FFFFFFFF0f0f0f0f0f0FFFFFFFFF"    $"